sp_widget.client_script:
api.controller = function() {
  /* widget controller */
    var c = this;

    // Initialize loading state
    c.loading = false; 

    // Field object for sn-record-picker (initialized by Server Script)
    c.user_picker = c.data.user_picker;

    // Watch for changes in the user_picker value
    $scope.$watch('c.user_picker.field.value', function (newValue, oldValue) {
        // If the user is changed (or cleared), we might need to reset search results
        if (newValue !== oldValue) {
            // Optionally clear existing results when the selected user changes
            // c.data.results = { incidents: [], changes: [], problems: [], hasSearched: false };
            c.data.error = null;
        }
    });

    c.searchTickets = function() {
        var userId = c.user_picker.field.value;
        c.data.error = null;

        if (!userId) {
            // If user ID is empty, set an error and disable loading
            c.data.error = "Please select a user to search for tickets.";
            c.data.results = { incidents: [], changes: [], problems: [], hasSearched: false };
            c.loading = false; // MUST ensure loading is turned off
            return;
        }

        c.loading = true;

        // Send the user ID to the server for the 'search' action
        c.server.get({
            action: 'search',
            userId: userId
        }).then(function(response) {
            // The server response updates c.data automatically
            // If the server set an error, it will show up via ng-if
            c.loading = false; // Turn off loading indicator
        }).catch(function(error) {
            // Handle HTTP or server-side error
            c.data.error = "An unexpected error occurred during search.";
            console.error("Server search error:", error);
            c.loading = false; // Always turn off loading on error
        });
    };

    // Helper function to build the native list view URL
    c.getListViewUrl = function(type, userId) {
        var table = '';
        var userField = '';
        if (type === 'incidents') {
            table = 'incident';
            userField = 'caller_id';
        } else if (type === 'changes') {
            table = 'change_request';
            userField = 'requested_by'; // Or 'assigned_to', depending on requirement
        } else if (type === 'problems') {
            table = 'problem';
            userField = 'assigned_to'; // Using assigned_to for problems
        }

        if (table && userId) {
            // URL to open the list view filtered by user's sys_id
            return table + '_list.do?sysparm_query=' + userField + '=' + userId;
        }
        return '#'; // Return hash if data is missing
    };

    // The ng-init logic in HTML runs c.searchTickets() on load if hasSearched is false.
    // If the widget loads with a pre-filled user (due to Server Script initialization), 
    // the initial search will now run and disable the loading spinner correctly.
};

sp_widget.css:
/*
 * Custom styles for the User Ticket Lookup widget.
 * Using .state-active and .state-closed to ensure the label colors are consistent
 * across different ServiceNow themes/styles, which can sometimes override the 
 * standard label-success/label-danger if not specific enough.
 */

.state-active {
    background-color: #5cb85c !important; /* Green */
    color: #fff !important;
}

.state-closed {
    background-color: #d9534f !important; /* Red */
    color: #fff !important;
}

/* Ensure the widget content is constrained nicely */
.panel-body {
    padding: 15px;
}

/* Styling for the record picker to fill its space */
.sn-record-picker {
    width: 100%;
}

sp_widget.script:
(function() {
    /*
     * This script handles two modes:
     * 1. Initialization (Input is null): Sets up the current user's details for the initial search.
     * 2. Data Fetch (Input is present): Executes GlideRecord queries based on the user's sys_id.
     */

    // Helper function to query a table and return a result array
    function getRecords(tableName, userId, limit) {
        var results = [];
        var gr = new GlideRecord(tableName);

        // Query condition: Tickets where the user is the caller or requested for (adjust as needed)
        var userField = (tableName === 'change_request') ? 'requested_by' : 'caller_id';

        gr.addQuery(userField, userId);
        gr.orderByDesc('sys_created_on');
        gr.setLimit(limit); // Limit to 10 records for display
        gr.query();

        while (gr.next()) {
            results.push({
                number: gr.getDisplayValue('number'),
                sys_id: gr.getValue('sys_id'),
                short_description: gr.getValue('short_description'),
                state_value: gr.getValue('state'), // Raw value for logic
                state_display: gr.getDisplayValue('state'), // Display value for UI
                is_active: gr.getValue('active') // Boolean indicator
            });
        }
        return results;
    }

    // --- 1. Initialization (Runs on widget load) ---
    if (!input) {
        var userId = gs.getUserID();

        // Lookup user's display name explicitly
        var userName = 'Unknown User';
        var userGR = new GlideRecord('sys_user');
        if (userGR.get(userId)) {
             // Use explicit field name for safety
            userName = userGR.getDisplayValue('name'); 
        }

        // Pre-populate the user picker field with the current user's data
        data.user_picker = {
            field: {
                value: userId,
                displayValue: userName
            }
        };
        // Initialize results structure
        data.results = {
            hasSearched: false,
            incidents: [],
            changes: [],
            problems: []
        };
        data.foundUserName = userName;
        data.userId = userId;
        return;
    }

    // --- 2. Data Fetch (Runs when c.searchTickets() is called) ---
    if (input && input.action === 'search') {
        var userId = input.userId;
        data.error = null;

        if (!userId) {
            data.error = "Please select a user to search for tickets.";
            data.results = { incidents: [], changes: [], problems: [], hasSearched: true };
            return;
        }

        // Fetch User Name for display in the header
        var userGR = new GlideRecord('sys_user');
        if (userGR.get(userId)) {
            // Use explicit field name for safety
            data.foundUserName = userGR.getDisplayValue('name'); 
            data.userId = userId;
        } else {
            data.foundUserName = "User Not Found";
            data.error = "The selected user ID does not exist.";
            data.results = { incidents: [], changes: [], problems: [], hasSearched: true };
            return;
        }

        // Fetch the tickets
        var limit = 10;
        data.results = {
            incidents: getRecords('incident', userId, limit),
            changes: getRecords('change_request', userId, limit),
            problems: getRecords('problem', userId, limit),
            hasSearched: true // Indicate that a search has been executed
        };

        data.userId = userId; 
    }

})();
